  maxTags?: HelixCombobox["maxTags"];
  /** Accessible name for the list, which has no visible one of its own. */
  "list-label"?: HelixCombobox["listLabel"];
  /** Accessible name for the list, which has no visible one of its own. */
  listLabel?: HelixCombobox["listLabel"];
